  "codebook": {
    "definition": "Credit-claiming is defined as any statement or action by a senator designed to generate the belief among constituents or relevant political actors that the senator is personally or jointly responsible for a positive government outcome or for delivering a specific, desirable benefit.",
    "clarification": "To classify a text as credit-claiming (1), there must be a completed, positive, or successful government outcome (e.g., a grant awarded, a bill or amendment passed, a project approved, or a rule waived) and the senator must explicitly link themselves to that success (e.g., claiming they 'secured,' 'helped secure,' 'authored,' 'requested,' or 'fought for' the outcome). A primary indicator is the announcement of federal funds or grants arriving in the senator's home state, or the inclusion of a senator's specific amendment in passed legislation.",
    "positive_examples": [
      {
        "document_id": "2318",
        "explanation": "Senator Durbin explicitly claims personal credit for securing an expedited environmental review and facilitating the return of a project to the national priority list."
      },
      {
        "document_id": "1862",
        "explanation": "Senators Baucus and Tester claim credit for delivering on a promise to secure $12.5 million for military projects in Butte, Montana, noting they 'went to bat for these dollars.'"
      },
      {
        "document_id": "1257",
        "explanation": "Senator DeWine claims credit for a local firefighting grant that was awarded 'as part of his Firefighter Investment and Response Enhancement (FIRE) Act,' which he wrote and passed."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming (0) if the senator is merely proposing, introducing, or cosponsoring a bill that has not yet passed, or is asking an agency to take action without a completed positive outcome. These actions constitute 'position-taking' or 'advocacy.' Additionally, exclude general statements of support or opposition, committee questioning, oversight hearings without a claimed outcome, symbolic or commemorative resolutions, and receiving awards from outside advocacy groups.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Senator Kennedy introduces stem cell legislation. This is position-taking because it represents proposing a bill rather than achieving a concrete outcome or securing a benefit."
      },
      {
